import{_ as a}from"./chunks/img.Dck1PxLc.js";import{_ as e,C as t,c as r,o as n,j as l,G as i,a0 as s,a as o}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Om bouleakademin","description":"","frontmatter":{},"headers":[],"relativePath":"sv/about.md","filePath":"sv/about.md"}');const g=e({name:"sv/about.md"},[["render",function(e,d,g,k,p,m){const h=t("AdBanner"),u=t("AdInArticle");return n(),r("div",null,[d[0]||(d[0]=l("h1",{id:"om-bouleakademin",tabindex:"-1"},[o("Om bouleakademin "),l("a",{class:"header-anchor",href:"#om-bouleakademin","aria-label":'Permalink to "Om bouleakademin"'},"​")],-1)),i(h),d[1]||(d[1]=s('<h2 id="en-passion-for-boule" tabindex="-1">En passion för boule <a class="header-anchor" href="#en-passion-for-boule" aria-label="Permalink to &quot;En passion för boule&quot;">​</a></h2><p>Välkommen till Pétanque Academy, där en djupt rotad passion för boule har varit en drivkraft i över 45 år. Min resa med denna sport har varit präglad av engagemang, skicklighet och ständig entusiasm.</p><p>Boule är inte bara ett spel; det är ett sätt att skapa kontakter, strategier och njuta av naturen, och jag har haft turen att uppleva dess många aspekter i nästan ett halvt sekel. Oavsett om det gäller den exakta placeringen av ett boule eller kamratskapet i terrängen, är mitt engagemang för boule lika starkt som någonsin.</p><p><img src="'+a+'" alt="Patrik Wiik with friends"></p><p><em>Att dela denna passion med vänner är verkligen det som gör boule så speciellt. De otaliga timmarna som spenderas på terrängen, fyllda med skratt, vänskaplig tävling och gemensamma berättelser, bygger band som varar livet ut.</em></p><hr><h2 id="mitt-uppdrag" tabindex="-1">Mitt uppdrag <a class="header-anchor" href="#mitt-uppdrag" aria-label="Permalink to &quot;Mitt uppdrag&quot;">​</a></h2><p>Pétanque Academys uppdrag är att hjälpa elitspelare att frigöra sin fulla potential genom att ta itu med det mentala spelet – den ofta förbisedda aspekten som skiljer bra spelare från fantastiska.</p><p>Genom den här webbplatsen delar jag:</p><ul><li><strong>Mentala spelramverk</strong> utvecklade från årtionden av erfarenhet</li><li><strong>Praktiska verktyg och mallar</strong> för målsättning och träning</li><li><strong>Workshop-metoder</strong> för att bygga psykologisk trygghet</li><li><strong>Evidensbaserade metoder</strong> för prestation under press</li></ul><p>Det här handlar inte om teknisk coachning – det handlar om att skapa den mentala grunden som gör att dina tekniska färdigheter kan glänsa när det gäller som mest.</p><hr><h2 id="varfor-jag-skapade-den-har-webbplatsen" tabindex="-1">Varför jag skapade den här webbplatsen <a class="header-anchor" href="#varfor-jag-skapade-den-har-webbplatsen" aria-label="Permalink to &quot;Varför jag skapade den här webbplatsen&quot;">​</a></h2><p>Efter över 45 år inom boule har jag sett otaliga begåvade spelare kämpa inte med tekniken, utan med:</p><ul><li><strong>Inre kritiker</strong> som förstör självförtroendet efter misstag</li><li><strong>Press</strong> som gör att de spelar annorlunda i tävling</li><li><strong>Brist på struktur</strong> i mental träning</li><li><strong>Isolering</strong> i sin utvecklingsresa</li></ul><p>Den här webbplatsen finns för att ändra på det. Allt innehåll här är utformat för att vara omedelbart praktiskt – mallar du kan kopiera, ramverk du kan tillämpa idag och verktyg som fungerar i verklig konkurrens.</p><hr>',17)),i(u),d[2]||(d[2]=s('<h2 id="kontakta-oss" tabindex="-1">Kontakta oss <a class="header-anchor" href="#kontakta-oss" aria-label="Permalink to &quot;Kontakta oss&quot;">​</a></h2><p>Jag vill gärna höra från dig! Oavsett om du har frågor, vill dela med dig av dina erfarenheter eller är intresserad av workshops och utbildningar, tveka inte att kontakta mig.</p><h3 id="kontaktinformation" tabindex="-1">Kontaktinformation <a class="header-anchor" href="#kontaktinformation" aria-label="Permalink to &quot;Kontaktinformation&quot;">​</a></h3><p><strong>E-post:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="hjalp-mig-att-forbattra-den-har-webbplatsen" tabindex="-1">Hjälp mig att förbättra den här webbplatsen <a class="header-anchor" href="#hjalp-mig-att-forbattra-den-har-webbplatsen" aria-label="Permalink to &quot;Hjälp mig att förbättra den här webbplatsen&quot;">​</a></h2><p>Din feedback är ovärderlig! Den här webbplatsen utvecklas ständigt baserat på vad elitspelare faktiskt behöver.</p><h3 id="jag-vill-garna-hora-fran-dig-om" tabindex="-1">Jag vill gärna höra från dig om: <a class="header-anchor" href="#jag-vill-garna-hora-fran-dig-om" aria-label="Permalink to &quot;Jag vill gärna höra från dig om:&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Vad skulle hjälpa dig mest?</p><ul><li><p><strong>Vilket innehåll skulle du vilja se mer av?</strong></p><ul><li>Fler mentala speltekniker?</li><li>Fler praktiska mallar?</li><li>Fallstudier från elitspelare?</li></ul></li><li><p><strong>Vad saknas på webbplatsen?</strong></p><ul><li>Ämnen som inte behandlats?</li><li>Verktyg du önskar fanns?</li><li>Resurser du inte hittar?</li></ul></li><li><p><strong>Vad fungerar bra?</strong></p><ul><li>Vilka sidor har varit mest användbara?</li><li>Vilka verktyg har du egentligen använt?</li><li>Vad gjorde störst skillnad för dig?</li></ul></li><li><p><strong>Hur kan jag göra det bättre?</strong></p><ul><li>Navigationsförbättringar?</li><li>Innehållsorganisation?</li><li>Fler exempel?</li><li>Olika format?</li></ul></li></ul></div><h3 id="skicka-mig-din-feedback" tabindex="-1">Skicka mig din feedback <a class="header-anchor" href="#skicka-mig-din-feedback" aria-label="Permalink to &quot;Skicka mig din feedback&quot;">​</a></h3><p><strong>Mejla dina tankar till:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Förslag på ämnesrader:</strong></p><ul><li>&quot;Webbplatsfeedback: [Ditt ämne]&quot;</li><li>&quot;Innehållsförfrågan: [Vad du behöver]&quot;</li><li>&quot;Framgångssaga: [Hur den hjälpte]&quot;</li><li>&quot;Förslag: [Din idé]&quot;</li></ul><p><strong>Vad som ska inkluderas:</strong></p><ul><li>Din nuvarande nivå/erfarenhet</li><li>Vad du arbetar med</li><li>Specifik feedback eller önskemål</li><li>Eventuella framgångshistorier med innehållet</li></ul><hr><h2 id="vad-andra-sager" tabindex="-1">Vad andra säger <a class="header-anchor" href="#vad-andra-sager" aria-label="Permalink to &quot;Vad andra säger&quot;">​</a></h2><details class="details custom-block"><summary>Feedback från elitspelare</summary><p><em>&quot;Det mentala spelinnehållet har helt förändrat hur jag närmar mig tävling. Bara Inner Coach-ramverket var värt att hitta den här webbplatsen.&quot;</em> — Regional mästare, Frankrike</p><p><em>&quot;Äntligen någon som förstår tekniken är inte problemet. Workshopmetoden gav vår klubb ett helt nytt sätt att träna.&quot;</em> — Landslagsspelare, Sverige</p><p><em>&quot;Målmallen och dagboksmallen är precis vad jag behövde. Enkla, praktiska och faktiskt användbara.&quot;</em> — Turneringsspelare, Spanien</p></details><hr><h2 id="om-innehallet" tabindex="-1">Om innehållet <a class="header-anchor" href="#om-innehallet" aria-label="Permalink to &quot;Om innehållet&quot;">​</a></h2><p>Allt innehåll på den här webbplatsen är:</p><ul><li><strong>Gratis och tillgänglig</strong> - Inga betalväggar, inget dolt innehåll</li><li><strong>Praktiskt och användbart</strong> - Mallar du kan använda idag</li><li><strong>Evidensbaserad</strong> - Byggd på psykologisk forskning och mer än 45 års erfarenhet</li><li><strong>Uppdateras kontinuerligt</strong> - Nytt innehåll läggs till baserat på din feedback</li></ul><hr><h2 id="sekretess-och-cookies" tabindex="-1">Sekretess och cookies <a class="header-anchor" href="#sekretess-och-cookies" aria-label="Permalink to &quot;Sekretess och cookies&quot;">​</a></h2><p>Den här webbplatsen använder Google AdSense för att stödja sin drift. Genom att använda webbplatsen godkänner du Googles användning av cookies för annonsanpassning och analys.</p><p><strong>Vi respekterar din integritet:</strong></p><ul><li>Inga personuppgifter samlas in utöver standardanalys</li><li>Inga e-postlistor eller skräppost</li><li>Kontaktinformationen används endast för att svara på dina meddelanden</li></ul><hr><h2 id="anslut-och-dela" tabindex="-1">Anslut och dela <a class="header-anchor" href="#anslut-och-dela" aria-label="Permalink to &quot;Anslut och dela&quot;">​</a></h2><p>Om du tycker att detta innehåll är värdefullt:</p><ul><li><strong>Dela det</strong> med dina träningspartners</li><li><strong>Rekommendera det</strong> till din klubb</li><li><strong>Länk till det</strong> från dina egna källor</li><li><strong>Ge feedback</strong> för att förbättra det</li></ul><p>Tillsammans kan vi höja det mentala boulespelet världen över.</p><hr>',34)),i(h),d[3]||(d[3]=l("p",null,[l("strong",null,"Tack för att du är en del av Bouleakademin!")],-1)),d[4]||(d[4]=l("p",null,[l("em",null,"— Patrik Wiik")],-1))])}]]);export{d as __pageData,g as default};
